  'help.faq.cantLogin.q': 'Je ne peux pas me connecter à mon compte',
  'help.faq.cantLogin.a': 'Assure-toi d\'utiliser le bon email et mot de passe. Si tu as oublié ton mot de passe, clique sur "Mot de passe oublié ?" sur l\'écran de connexion. Si le problème persiste, crée un ticket de support.',
  'help.faq.notReceiving.q': 'Je ne reçois pas d\'emails',
  'help.faq.notReceiving.a': 'Vérifie d\'abord ton dossier Spam. Assure-toi que ton stockage n\'est pas plein. Si le problème continue, vérifie que l\'expéditeur a la bonne adresse email et crée un ticket de support.',
  'help.faq.cantSend.q': 'Je ne peux pas envoyer d\'emails',
  'help.faq.cantSend.a': 'Vérifie ta connexion internet et que l\'adresse email du destinataire est correcte. Vérifie si tu as des pièces jointes trop lourdes (max 25 Mo). Essaie encore dans quelques minutes.',
  'help.faq.forgotPassword.q': 'J\'ai oublié mon mot de passe',
  'help.faq.forgotPassword.a': 'Sur l\'écran de connexion, clique sur "Mot de passe oublié ?" et suis les instructions pour réinitialiser ton mot de passe via ton adresse email de récupération.',
  'help.faq.accountSecurity.q': 'Je pense que mon compte a été compromis',
  'help.faq.accountSecurity.a': 'Change immédiatement ton mot de passe. Vérifie ton dossier Envoyés pour des messages que tu n\'as pas envoyés. Active l\'authentification à deux facteurs dans Paramètres > Sécurité. Si besoin, crée un ticket de support urgent.',
  'help.faq.appAccess.q': 'Comment accéder à l\'application sur mobile ?',
  'help.faq.appAccess.a': 'Tu peux accéder à Chatyy via n\'importe quel navigateur mobile à chatyy.com.br, ou télécharger notre application depuis le store de ton appareil.',

  // Privacy modal
  'privacy.title': 'Politique de Confidentialité',
  'privacy.subtitle': 'Comment nous protégeons et gérons tes données',
  'privacy.lastUpdated': 'Dernière mise à jour : Mars 2026',
  'privacy.dataCollection.title': 'Collecte de Données',
  'privacy.dataCollection.body': 'Nous ne collectons que les informations nécessaires pour fournir notre service email : ton nom, ton adresse email, et le contenu des messages que tu envoies et reçois. Nous ne vendons ni ne partageons tes données personnelles avec des tiers à des fins de marketing.',
  'privacy.dataUsage.title': 'Comment Nous Utilisons Tes Données',
  'privacy.dataUsage.body': 'Tes données sont utilisées exclusivement pour faire fonctionner et améliorer le service email, y compris la livraison des messages, le filtrage des spams, la fourniture de fonctionnalités alimentées par l\'IA (avec ton consentement), et le maintien de la sécurité du compte.',
  'privacy.dataSecurity.title': 'Sécurité des Données',
  'privacy.dataSecurity.body': 'Nous utilisons un chiffrement standard de l\'industrie (TLS/SSL) pour toutes les données en transit et au repos. Les sessions sont protégées par des jetons chiffrés et une protection CSRF. Nous auditons régulièrement nos pratiques de sécurité.',
  'privacy.cookies.title': 'Cookies & Stockage Local',
  'privacy.cookies.body': 'Nous utilisons des cookies essentiels et du stockage local pour maintenir ta session, mémoriser tes préférences (thème, langue) et offrir une expérience fluide. Nous n\'utilisons pas de cookies de suivi de tiers.',
  'privacy.thirdParties.title': 'Services Tiers',
  'privacy.thirdParties.body': 'Nous pouvons utiliser des services tiers pour des fonctionnalités spécifiques comme les fonctionnalités IA (Anthropic Claude) et les notifications push. Ces services sont soumis à leurs propres politiques de confidentialité et ne traitent que les données minimales nécessaires.',
  'privacy.rights.title': 'Tes Droits',
  'privacy.rights.body': 'Tu as le droit d\'accéder, de corriger, d\'exporter ou de supprimer tes données personnelles à tout moment. Tu peux gérer tes données via les Paramètres ou en contactant notre équipe de support.',
  'privacy.contact.title': 'Contacte-nous',
  'privacy.contact.body': 'Pour des questions liées à la confidentialité ou des demandes de données, contacte-nous à privacy@chatyy.com.br. Nous te répondrons dans les 30 jours.',

  // Terms modal
  'terms.title': 'Conditions d\'Utilisation',
  'terms.subtitle': 'Directives pour utiliser Chatyy',
  'terms.lastUpdated': 'Dernière mise à jour : mars 2026',
  'terms.acceptance.title': 'Acceptation des Conditions',
  'terms.acceptance.body': 'En accédant ou en utilisant Chatyy, tu acceptes d\'être lié par ces Conditions d\'Utilisation. Si tu n\'acceptes pas une partie de ces conditions, tu ne peux pas utiliser le service.',
  'terms.services.title': 'Description des Services',
  'terms.services.body': 'Chatyy fournit des services de communication par email, y compris l\'envoi, la réception et la gestion des emails, ainsi que des fonctionnalités alimentées par IA, l\'intégration de calendrier et des capacités de visioconférence.',
  'terms.accounts.title': 'Comptes Utilisateurs',
  'terms.accounts.body': 'Tu es responsable de la sécurité de tes identifiants de compte. Tu ne dois pas partager ton mot de passe ni permettre un accès non autorisé à ton compte. Tu dois avoir au moins 13 ans pour utiliser ce service.',
  'terms.conduct.title': 'Utilisation Acceptable',
  'terms.conduct.body': 'Tu acceptes de ne pas utiliser le service pour envoyer du spam, des malwares, du phishing ou tout contenu illégal. Tu ne dois pas tenter d\'accéder aux comptes d\'autres utilisateurs ou de perturber l\'infrastructure du service.',
  'terms.content.title': 'Propriété du Contenu',
  'terms.content.body': 'Tu conserves la propriété de tout le contenu que tu crées et envoies via le service. Nous ne revendiquons pas la propriété de tes emails ou pièces jointes. Nous pouvons traiter le contenu si nécessaire pour fournir le service.',
  'terms.limitation.title': 'Limitation de Responsabilité',
  'terms.limitation.body': 'Chatyy est fourni "tel quel". Nous visons 99,9 % de disponibilité mais ne garantissons pas un service ininterrompu. Nous ne sommes pas responsables des dommages indirects, accessoires ou consécutifs résultant de ton utilisation du service.',
  'terms.termination.title': 'Résiliation de Compte',
  'terms.termination.body': 'Nous pouvons suspendre ou résilier des comptes qui violent ces conditions. Tu peux supprimer ton compte à tout moment via les Paramètres. Après résiliation, tes données seront supprimées dans les 30 jours.',
  'terms.changes.title': 'Modifications des Conditions',
  'terms.changes.body': 'Nous pouvons mettre à jour ces conditions de temps en temps. Nous te notifierons des changements significatifs par email ou notification dans l\'application. L\'utilisation continue du service après les changements constitue une acceptation des conditions mises à jour.',

